<?php
require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $db=getDB(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf_token']??null)){ $id=(int)post('user_id'); $status=(string)post('status'); if(in_array($status,['active','inactive','banned'],true)&&$id!==(int)$_SESSION['user_id']){$db->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]); flash('success','User status updated.'); redirect(appUrl('admin/users.php'));} } $users=$db->query('SELECT u.*,COALESCE(w.balance,0) balance,COALESCE(w.total_invested,0) total_invested FROM users u LEFT JOIN wallets w ON w.user_id=u.id ORDER BY u.created_at DESC')->fetchAll(); $pageTitle='Users';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">ACCOUNTS</span><h1>Users</h1></div><?php foreach(consumeFlashes() as $f): ?><div class="alert <?= e($f['type']) ?>"><?= e($f['message']) ?></div><?php endforeach; ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Balance</th><th>Invested</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><br><small><?= e($u['username']) ?><?= $u['is_admin']?' · admin':'' ?></small></td><td><?= e($u['email']) ?></td><td><?= formatCurrency($u['balance']) ?></td><td><?= formatCurrency($u['total_invested']) ?></td><td><span class="badge <?= e($u['status']) ?>"><?= e(ucfirst($u['status'])) ?></span></td><td><?php if(!$u['is_admin']): ?><form method="post" class="inline-form"><?= csrfField() ?><input type="hidden" name="user_id" value="<?= e($u['id']) ?>"><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="banned">Banned</option></select><button class="btn small ghost" type="submit">Save</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
